http-node-fetch.command:
node - <<'JS'
(async () => {
  const resp = await fetch('http://127.0.0.1:3100/v1/chat/completions', {
    method: 'POST',
    headers: {'content-type': 'application/json'},
    body: JSON.stringify({model: 'local-fake-model', messages: [{role: 'user', content: 'ping'}]}),
  });
  console.log(resp.status);
  console.log(await resp.text());
})();
JS

