http-rust-reqwest.command:
mkdir -p /tmp/http-reqwest-smoke/src;
cat > /tmp/http-reqwest-smoke/Cargo.toml <<'TOML'
[package]
name = "http-reqwest-smoke"
version = "0.1.0"
edition = "2021"

[dependencies]
reqwest = { version = "0.12", features = ["json"] }
serde_json = "1.0"
tokio = { version = "1.37", features = ["macros", "rt-multi-thread"] }
TOML
cat > /tmp/http-reqwest-smoke/src/main.rs <<'RS'
use reqwest::Client;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
  let client = Client::new();
  let resp = client
    .post("http://127.0.0.1:3100/v1/chat/completions")
    .json(&serde_json::json!({
      "model": "local-fake-model",
      "messages": [{"role": "user", "content": "ping"}],
    }))
    .send()
    .await?;
  println!("{}", resp.status());
  println!("{}", resp.text().await?);
  Ok(())
}
RS
cd /tmp/http-reqwest-smoke && cargo run --quiet
